import { eventListeners, Placement } from '@popperjs/core';
import { AnimatePresence, motion, Variants } from 'framer-motion';
import React, {
  forwardRef,
  useCallback,
  useMemo,
  useRef,
  useState,
} from 'react';
import { usePopper } from 'react-popper';
import styled from 'styled-components';

import AnimationsJS from '@dynatrace/strato-design-tokens/animations-js';
import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { TooltipProps } from './Tooltip.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { useOverlayStacking } from '../../core/hooks/useOverlayStacking.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Text } from '../../typography/Text.js';
import {
  observeOverlaySize,
  observeAnimationDone,
} from '../utils/popper-modifiers.js';

const TOOLTIP_OFFSET = 8;

interface TooltipElementProps
  extends WithChildren,
    StylingProps,
    DataTestId,
    Pick<TooltipProps, 'placement' | 'fallbackPlacements' | 'id'> {
  /** Reference to the trigger element */
  triggerElement?: Element;
  /** Callback triggered when the mouse leaves the tooltip element. */
  onMouseLeave?: (e: React.MouseEvent<HTMLDivElement>) => void;
  /** Callback triggered when the tooltip hover state changes. */
  onTooltipHovered?: (isTooltipHovered: boolean) => void;
}

// #region StyledComponents
const StyledTooltipElement = /* @__PURE__ */ styled('div')({
  '&[data-popper-placement^="top"]': {
    '&::after': {
      content: '""',
      position: 'absolute',
      width: '100%',
      height: TOOLTIP_OFFSET,
      left: 0,
      bottom: -TOOLTIP_OFFSET,
    },
    '& > div': {
      transformOrigin: 'center bottom',
    },
  },

  '&[data-popper-placement^="bottom"]': {
    '&::after': {
      content: '""',
      position: 'absolute',
      width: '100%',
      height: TOOLTIP_OFFSET,
      left: 0,
      top: -TOOLTIP_OFFSET,
    },
    '& > div': {
      transformOrigin: 'center top',
    },
  },

  '&[data-popper-placement^="left"]': {
    '&::after': {
      content: '""',
      position: 'absolute',
      height: '100%',
      width: TOOLTIP_OFFSET,
      top: 0,
      right: -TOOLTIP_OFFSET,
    },
    '& > div': {
      transformOrigin: 'right center',
    },
  },

  '&[data-popper-placement^="right"]': {
    '&::after': {
      content: '""',
      position: 'absolute',
      height: '100%',
      width: TOOLTIP_OFFSET,
      top: 0,
      left: -TOOLTIP_OFFSET,
    },
    '& > div': {
      transformOrigin: 'left center',
    },
  },

  maxWidth: '200px',
  wordBreak: 'normal',
  overflowWrap: 'anywhere',
  pointerEvents: 'auto',
});

const StyledAnimationWrapper = /* @__PURE__ */ styled(motion.div)({
  color: Colors.Text.OnAccent.Default,
  background: Colors.Background.Container.Neutral.Accent,
  paddingTop: Spacings.Size6,
  paddingBottom: Spacings.Size6,
  paddingLeft: Spacings.Size8,
  paddingRight: Spacings.Size8,
  borderRadius: Borders.Radius.Field.Subdued,
});
// #endregion

const animationVariants: Variants = {
  enter: {
    transform: 'scale(1)',
    opacity: 1,
    transition: {
      duration: AnimationsJS.Open.Duration.Fast,
      ease: AnimationsJS.Open.Easing,
    },
  },
  exit: {
    transform: 'scale(0)',
    opacity: 0.2,
    transition: {
      duration: AnimationsJS.Close.Duration.Fast,
      ease: AnimationsJS.Close.Easing,
    },
  },
};

/** The tooltip element / portal that is being rendered into the tooltip */
export const TooltipElement = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  TooltipElementProps
>((props: TooltipElementProps, forwardedRef) => {
  const {
    children,
    placement,
    triggerElement,
    id,
    fallbackPlacements: fallbackPlacementsProp,
    onMouseLeave,
    onTooltipHovered,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  const [tooltipRef, setTooltipRef] = useState<HTMLDivElement | null>(null);

  // Forwards the ref to the opened tooltip.
  // DISCUSS: This stays on the tooltip element rather than the wrapping span
  // in order to not break the behavior and api. We should definitely
  // think about switching this up.
  const mergedTooltipRef = useMergeRefs([forwardedRef, setTooltipRef]);

  // Defines fallback placements. In order to flip _correctly_, we adjust
  // the fallback list based on the desired positioning.
  const fallbackPlacements = useMemo<Placement[] | undefined>(() => {
    if (fallbackPlacementsProp) {
      return fallbackPlacementsProp;
    }

    switch (placement) {
      case 'top':
        return ['bottom', 'left', 'right'];
      case 'bottom':
        return ['top', 'left', 'right'];
      case 'left':
        return ['right', 'top', 'bottom'];
      case 'right':
        return ['left', 'top', 'bottom'];
    }
  }, [placement, fallbackPlacementsProp]);

  const { styles, attributes } = usePopper(triggerElement, tooltipRef, {
    placement,
    modifiers: [
      {
        name: 'offset',
        options: {
          offset: [0, TOOLTIP_OFFSET],
        },
      },
      {
        name: 'flip',
        options: {
          fallbackPlacements,
        },
      },
      observeOverlaySize,
      observeAnimationDone,
      eventListeners,
    ],
  });

  // Get the zIndex for the stacked overlay to apply to the tooltip
  const stackingContext = useOverlayStacking(undefined, 'overlay');

  const tooltipHovered = useRef(false);

  const handleMouseLeaveTooltip = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      tooltipHovered.current = false;
      onMouseLeave?.(e);
      onTooltipHovered?.(tooltipHovered.current);
    },
    [onMouseLeave, onTooltipHovered],
  );

  const tooltipContent = (
    <AnimatePresence>
      <StyledTooltipElement
        ref={mergedTooltipRef}
        style={{
          ...styles.popper,
          zIndex: stackingContext.style.zIndex,
          ...consumerStyle,
        }}
        className={consumerClassName}
        data-testid={dataTestId}
        role="tooltip"
        onMouseEnter={() => {
          tooltipHovered.current = true;
          onTooltipHovered?.(tooltipHovered.current);
        }}
        onMouseLeave={handleMouseLeaveTooltip}
        {...attributes.popper}
        id={id}
      >
        <StyledAnimationWrapper
          variants={animationVariants}
          initial="exit"
          animate="enter"
          exit="exit"
        >
          {typeof children === 'string' ? (
            <Text textStyle="small-emphasized" as="p">
              {children}
            </Text>
          ) : (
            children
          )}
        </StyledAnimationWrapper>
      </StyledTooltipElement>
    </AnimatePresence>
  );

  return tooltipContent;
});

(
  TooltipElement as typeof TooltipElement & { displayName: string }
).displayName = 'TooltipElement';
